34	  MotionMediaFamily family = 1;
35	  MotionMediaRole role = 2;
36	  string group_id = 3;
37	  int64 presentation_timestamp_us = 4;
38	  bool has_embedded_video = 5;
39	}
40	
41	message AttachmentPayload {
42	  oneof payload {
43	    S3Object s3_object = 1;
44	  }
45	
46	  MotionMedia motion_media = 10;
47	
48	  message S3Object {
49	    StorageS3Config s3_config = 1;
50	    // key is the S3 object key.
51	    string key = 2;
